-- Normalize known Prisma SQLite epoch milliseconds and UTC TEXT dates.
-- All guards and updates run inside the migration transaction.
CREATE TABLE "_PorkexDateGuard" ("valid" INTEGER NOT NULL CHECK ("valid" = 1));

INSERT INTO "_PorkexDateGuard" SELECT CASE WHEN "createdAt" IS NULL THEN 1 WHEN typeof("createdAt")='integer' AND CASE WHEN substr(strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END),-4)='.000' THEN strftime('%Y-%m-%dT%H:%M:%S',CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END,CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) ELSE strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) END || '+00:00' IS NOT NULL AND round(unixepoch(CASE WHEN substr(strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END),-4)='.000' THEN strftime('%Y-%m-%dT%H:%M:%S',CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END,CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) ELSE strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) END || '+00:00','subsec')*1000)="createdAt" THEN 1 WHEN typeof("createdAt")='text' AND (replace(replace(replace("createdAt",' ','T'),'Z','+00:00'),'.000+00:00','+00:00')=CASE WHEN substr(strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END),-4)='.000' THEN strftime('%Y-%m-%dT%H:%M:%S',CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END,CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) ELSE strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) END || '+00:00' OR replace(replace(replace("createdAt",' ','T'),'Z','+00:00'),'.000+00:00','+00:00') || '+00:00'=CASE WHEN substr(strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END),-4)='.000' THEN strftime('%Y-%m-%dT%H:%M:%S',CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END,CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) ELSE strftime('%Y-%m-%dT%H:%M:%f', CASE WHEN typeof("createdAt")='integer' THEN "createdAt"/1000.0 ELSE "createdAt" END, CASE WHEN typeof("createdAt")='integer' THEN 'unixepoch' ELSE '+0 seconds' END) END || '+00:00') THEN 1 ELSE 0 END FROM "User";
